    queue = deque([source])
    while queue:
        current = queue.popleft()
        if current == target:
            break
        for neighbor, weight in graph.get(current, []):
            if distance[neighbor] > distance[current] + weight:
                distance[neighbor] = distance[current] + weight
                path[neighbor] = path[current] + [neighbor]
                queue.append(neighbor)
    if distance[target] == float('inf'):
        return (float('inf'), None)
    else:
        return (distance[target], path[target])

def shortest_path(graph, source, target):
    import heapq

    # Initialize the distance dictionary and the path dictionary
    distances = {node: float("inf") for node in graph}
    paths = {source: None)  # None indicates no path yet, and the path to the None is just the start node
    distances[source] = 0

    # Priority queue to perform Dijkstra's algorithm
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reached the target node, we can stop the algorithm
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = paths[current_node]
            return (distances[target], path[::-1])

        # Otherwise, we're still building the path
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only update the distance if we found a shorter path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    # If we reached here, it means the target is unreachable
    return (float("inf"), None)

